const constructionCases:PortfolioCase[]=[
  {number:"01",title:"Corona School",location:"Ikoyi, Lagos",label:"Site Engineer",summary:"Structural execution and workforce coordination from foundation works through the reinforced-concrete frame.",images:imageSet("corona",7),tags:["Structural supervision","Bar-bending schedules","Drawing analysis","Quality control"],articleLabel:"Read project journal",journal:[
    {heading:"Project context",text:"The Corona School project required disciplined execution within an active urban environment. My responsibility was to translate architectural and structural information into coordinated site activity while protecting quality, sequence and programme."},{heading:"My role",text:"As Site Engineer, I supervised daily construction, interpreted structural drawings, prepared and checked bar-bending schedules, resolved drawing and reinforcement questions and coordinated artisans, labour and subcontractors."},{heading:"Execution",text:"I monitored setting-out, excavation, foundation elements, reinforcement, formwork, concrete placement and progressive frame construction. Work fronts were planned around labour, materials, inspections and the dependencies between structural and service activities."},{heading:"Leadership",text:"Clear daily instructions, checks before concrete and practical coordination helped the workforce understand priorities and reduce avoidable rework. I maintained close attention to dimensions, reinforcement details and workmanship."},{heading:"Result",text:"The structural phases advanced in an organised sequence and key milestones were achieved through detailed supervision and team coordination. The project strengthened my ability to turn technical information into reliable on-site delivery."}
  ]},
  {number:"02",title:"Kolapo Lawson Residence",location:"Ajuwon, Lagos",label:"Site Engineer",summary:"Partial demolition and reconstruction carefully joining retained building elements with new structural work.",images:imageSet("kolapo",6),tags:["Partial demolition","Reconstruction","Structural coordination","Roofing"],articleLabel:"Read project journal",journal:[
    {heading:"Project context",text:"This residential assignment involved selective demolition rather than a clean start. Existing elements had to be assessed, protected or removed before new foundations and structural components could be introduced."},{heading:"My role",text:"I coordinated demolition, interpreted the revised drawings, planned structural work, reviewed reinforcement requirements and supervised the workforce through reconstruction."},{heading:"The challenge",text:"New work had to align with retained portions of the residence. That made sequencing, dimensions and site judgement especially important because an error during demolition or interface construction could affect later stages."},{heading:"Execution",text:"I organised safe demolition zones, foundation preparation, reinforcement, concrete, blockwork and the roof structure while checking alignment between old and new construction."},{heading:"Result",text:"The reconstruction progressed from a complex altered structure into a coherent residential form. The experience strengthened my ability to manage uncertainty and coordinate renovation work where site conditions evolve as construction opens up the existing building."}
  ]},
  {number:"03",title:"Ecobank Branch",location:"Admiralty Way, Lekki Phase 1",label:"Site Engineer",summary:"A demanding commercial banking facility delivered through intensive multidisciplinary coordination and close-out management.",images:imageSet("ecobank",9),tags:["Commercial delivery","Cladding","Building services","Interior finishing"],articleLabel:"Read project journal",journal:[
    {heading:"Project context",text:"The Ecobank branch combined structural work, a distinctive façade, banking operations, interior finishes and building services within a demanding commercial programme."},{heading:"My role",text:"I supervised site execution, coordinated contractors and trades, analysed drawings, managed structural details and maintained alignment between architectural, structural and service requirements."},{heading:"The challenge",text:"The intensity increased during façade and finishing stages when multiple specialists needed access to the same work areas. Quality expectations were high and the delivery timetable required constant prioritisation."},{heading:"Execution",text:"I coordinated scaffolding, cladding, glazing, internal finishes, service interfaces, external works and outstanding items while continuing inspections and progress tracking. Decisions were communicated quickly so that one trade did not block another."},{heading:"Result",text:"The branch was delivered successfully as a functional branded facility. The project expanded my experience in commercial close-out, high-pressure coordination and managing the transition from structural construction to a polished operational environment."}
  ]},
  {number:"04",title:"Country Home",location:"Oke-Opo, Ilesa, Osun State",label:"Site Manager",summary:"End-to-end leadership of a large residential build with complex structural, masonry and roofing requirements.",images:imageSet("country",8),tags:["Site leadership","Resource planning","Residential delivery","Complex roofing"],articleLabel:"Read project journal",journal:[
    {heading:"Project context",text:"The Oke-Opo country home was a substantial residential project whose scale, location and roof geometry demanded hands-on site leadership and careful resource planning."},{heading:"My role",text:"As Site Manager, I carried responsibility for people, programme, materials, technical interpretation, quality and the coordination of all major work fronts."},{heading:"The challenge",text:"The project required dependable delivery outside Lagos, with close attention to material availability, workforce productivity and the relationship between the concrete frame, masonry and extensive roof structure."},{heading:"Execution",text:"I planned labour and materials, reviewed drawings, managed structural and blockwork activities, coordinated formwork and concrete, and supervised the progression into timber roof framing and covering."},{heading:"Result",text:"The project advanced through demanding structural and roofing milestones under coordinated site management. It reinforced my capacity to lead complex work with high accountability, especially where logistics and technical decisions must be managed together."}
  ]},
  {number:"05",title:"Pile Cap and Ground Beam Foundation",location:"Ondo Street, Banana Island, Lagos",label:"Site Engineer",summary:"A reinforcement intensive foundation package requiring accuracy in pile caps, ground beams and concrete operations.",images:imageSet("banana",5),tags:["Deep foundation","Pile caps","Ground beams","Structural QA"],articleLabel:"Read project journal",journal:[
    {heading:"Project context",text:"This Banana Island assignment focused on the substructure of a high-value development. The work demanded accuracy because pile caps and ground beams establish the load path for everything built above them."},{heading:"My role",text:"I supervised setting-out, excavation, pile-head preparation, reinforcement, formwork, concrete placement and the organisation of labour and materials."},{heading:"Technical focus",text:"The reinforcement-intensive details required close reading of structural drawings and bar schedules. I checked levels, dimensions, laps, spacing, cover and starter positions before approving work for concrete."},{heading:"Execution",text:"Activities were sequenced to keep excavation, blinding, block formwork, steel fixing and casting moving without compromising inspection. The team received clear instructions around structural tolerances and concrete readiness."},{heading:"Result",text:"The foundation package progressed with the required structural control. The project further developed my practical understanding of deep-foundation interfaces and the importance of quality assurance before permanent work is concealed."}
  ]},
  {number:"06",title:"Police Station Complex",location:"Ibeju-Lekki, Lagos",label:"Site and Project Manager",summary:"Project management of three parallel structures within one public sector development.",images:imageSet("police",12),tags:["Three structures","Project management","Resource allocation","Public infrastructure"],articleLabel:"Read project journal",journal:[
    {heading:"Project context",text:"The police station complex comprised three structures delivered within a single site. Each building had its own work fronts, but labour, materials, equipment and programme decisions had to be coordinated as one project."},{heading:"My role",text:"As Site and Project Manager, I led planning, technical coordination, workforce deployment, materials, progress control, quality checks and communication across the complex."},{heading:"The challenge",text:"Parallel construction creates competition for resources and can hide delays when attention is concentrated on one structure. The project required a clear view of dependencies and balanced allocation across foundations, frames, walls, roofs and finishes."},{heading:"Execution",text:"I organised work packages by building and milestone, coordinated reinforcement and formwork inspections, monitored concrete and blockwork, managed roofing progression and maintained visibility of constraints across the site."},{heading:"Result",text:"The three structures progressed through major structural and roofing stages under one coordinated programme. The experience demonstrated my ability to manage a multi-building development, direct several teams and maintain delivery focus across a broad site."}
  ]}
];

function Gallery({item,onZoom}:{item:PortfolioCase;onZoom:(src:string,alt:string)=>void}){if(!item.images.length&&!item.video)return <div className="gallery-empty">Case-study narrative available · Visuals to be added</div>;return <div className={`media-rail ${item.screenshots?"screenshots":""}`} aria-label={`${item.title} media gallery`}>{item.video&&<div className="media-frame media-video"><video controls playsInline preload="none" poster={item.video.poster}><source src={item.video.src} type="video/mp4"/>Your browser does not support video.</video><span>{item.video.title}</span></div>}{item.images.map((src,i)=><button className="media-frame" onClick={()=>onZoom(src,`${item.title} visual ${i+1}`)} key={src} aria-label={`Open ${item.title} image ${i+1}`}><img src={src} alt={`${item.title} visual ${i+1}`}/><span>View {String(i+1).padStart(2,"0")}</span></button>)}</div>}

