function PracticeJournalModal({journal,onClose}:{journal:PracticeJournal;onClose:()=>void}){return <div className="modal-shell practice-reader-shell" role="dialog" aria-modal="true" aria-labelledby="practice-journal-title" onMouseDown={event=>event.target===event.currentTarget&&onClose()}><article className="practice-reader"><button className="modal-close" onClick={onClose} aria-label="Close product practice journal">Close ×</button><header className="practice-reader-header"><div><span>{journal.number}</span><p>Product practice journal · {journal.readTime}</p></div><h2 id="practice-journal-title">{journal.title}</h2><h3>{journal.articleTitle}</h3><p>{journal.summary}</p><nav className="practice-reader-actions" aria-label={`${journal.title} journal options`}><a href={journal.href} target="_blank" rel="noreferrer">Open full journal <span>↗</span></a><a href={journal.href} download>Download PDF <span>↓</span></a></nav></header><div className="practice-pdf"><iframe src={`${journal.href}#view=FitH&toolbar=1&navpanes=0`} title={`${journal.title} product practice journal`}/><div className="practice-pdf-fallback"><p>If the journal does not appear on your device, open it in a new tab.</p><a href={journal.href} target="_blank" rel="noreferrer">Open journal</a></div></div></article></div>}

