export default function Home(){
 const [active,setActive]=useState<PortfolioCase|null>(null);
 const [activePractice,setActivePractice]=useState<PracticeJournal|null>(null);
 const [zoom,setZoom]=useState<{src:string;alt:string}|null>(null);
 const [showWelcome,setShowWelcome]=useState(true);
 const [theme,setTheme]=useState<"light"|"navy">("light");
 const [contactOpen,setContactOpen]=useState(false);
 const [contactPosition,setContactPosition]=useState<{x:number;y:number}|null>(null);
 const [contactDragging,setContactDragging]=useState(false);
 const contactRef=useRef<HTMLElement|null>(null);
 const ignoreContactClick=useRef(false);
 const contactDrag=useRef({active:false,moved:false,startX:0,startY:0,startLeft:0,startTop:0});
 const clampContactPosition=(x:number,y:number)=>{const margin=10;const rect=contactRef.current?.getBoundingClientRect();const width=rect?.width||48;const height=rect?.height||48;return{x:Math.min(Math.max(margin,x),Math.max(margin,window.innerWidth-width-margin)),y:Math.min(Math.max(margin,y),Math.max(margin,window.innerHeight-height-margin))}};
 useEffect(()=>{const saved=window.localStorage.getItem("portfolio-theme");const initial=saved==="light"||saved==="navy"?saved:window.matchMedia("(prefers-color-scheme: dark)").matches?"navy":"light";document.documentElement.dataset.theme=initial;setTheme(initial)},[]);
 useEffect(()=>{const timer=window.setTimeout(()=>setShowWelcome(false),5200);return()=>window.clearTimeout(timer)},[]);
 useEffect(()=>{const fn=(e:KeyboardEvent)=>{if(e.key==="Escape"){if(zoom)setZoom(null);else if(active)setActive(null);else if(activePractice)setActivePractice(null);else setContactOpen(false)}};window.addEventListener("keydown",fn);document.body.style.overflow=active||activePractice||zoom?"hidden":"";return()=>{window.removeEventListener("keydown",fn);document.body.style.overflow=""}},[active,activePractice,zoom]);
 useEffect(()=>{const close=(event:PointerEvent)=>{const target=event.target as HTMLElement;if(contactOpen&&!target.closest(".floating-contact"))setContactOpen(false)};document.addEventListener("pointerdown",close);return()=>document.removeEventListener("pointerdown",close)},[contactOpen]);
 useEffect(()=>{try{const saved=window.localStorage.getItem("portfolio-contact-position");if(saved){const parsed=JSON.parse(saved) as {x:number;y:number};if(Number.isFinite(parsed.x)&&Number.isFinite(parsed.y))window.requestAnimationFrame(()=>setContactPosition(clampContactPosition(parsed.x,parsed.y)))}}catch{}},[]);
 useEffect(()=>{const keepInView=()=>setContactPosition(current=>current?clampContactPosition(current.x,current.y):current);window.addEventListener("resize",keepInView);return()=>window.removeEventListener("resize",keepInView)},[]);
 const startContactDrag=(event:ReactPointerEvent<HTMLButtonElement>)=>{if(event.button!==0)return;const rect=event.currentTarget.getBoundingClientRect();contactDrag.current={active:true,moved:false,startX:event.clientX,startY:event.clientY,startLeft:rect.left,startTop:rect.top};event.currentTarget.setPointerCapture(event.pointerId)};
 const moveContactDrag=(event:ReactPointerEvent<HTMLButtonElement>)=>{const drag=contactDrag.current;if(!drag.active)return;const dx=event.clientX-drag.startX;const dy=event.clientY-drag.startY;if(!drag.moved&&Math.hypot(dx,dy)<6)return;if(!drag.moved){drag.moved=true;ignoreContactClick.current=true;setContactOpen(false);setContactDragging(true)}setContactPosition(clampContactPosition(drag.startLeft+dx,drag.startTop+dy))};
 const finishContactDrag=(event:ReactPointerEvent<HTMLButtonElement>)=>{const drag=contactDrag.current;if(!drag.active)return;drag.active=false;setContactDragging(false);if(event.currentTarget.hasPointerCapture(event.pointerId))event.currentTarget.releasePointerCapture(event.pointerId);if(drag.moved)setContactPosition(current=>{if(current)window.localStorage.setItem("portfolio-contact-position",JSON.stringify(current));return current})};
 const toggleContact=()=>{if(ignoreContactClick.current){ignoreContactClick.current=false;return}setContactOpen(value=>!value)};
 const toggleTheme=()=>setTheme(current=>{const next=current==="navy"?"light":"navy";document.documentElement.dataset.theme=next;window.localStorage.setItem("portfolio-theme",next);return next});
 const openZoom=(src:string,alt:string)=>setZoom({src,alt});
 return <main>
  <header className="site-header"><a className="brand" href="#top"><span>OLUSOLA AYODEJI EZEKIEL</span><small>Product Manager</small></a><nav><a href="#products">Product work</a><a href="#construction">Construction</a><a href="#rough-space">Rough Space</a><a href="#insights">Insights</a><a href="#about">About</a><button className={`theme-toggle ${theme==="navy"?"is-navy":""}`} type="button" onClick={toggleTheme} aria-label={theme==="navy"?"Switch to light mode":"Switch to navy dark mode"} title={theme==="navy"?"Light mode":"Navy dark mode"}><span className="theme-toggle-icon theme-toggle-sun" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3.5"/><path d="M12 2v2M12 20v2M4.93 4.93l1.42 1.42M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.42-1.42M17.66 6.34l1.41-1.41"/></svg></span><span className="theme-toggle-icon theme-toggle-moon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M20.2 15.3A8.5 8.5 0 0 1 8.7 3.8 8.5 8.5 0 1 0 20.2 15.3Z"/></svg></span><span className="theme-toggle-thumb" aria-hidden="true"/></button><a className="nav-cta" href="#contact">Let&apos;s talk</a></nav></header>
  <section className="hero" id="top"><div className="hero-copy"><p className="hero-label">Product strategy · Agile delivery · Technical coordination</p><h1>I turn complex ideas into <em>products people can use.</em></h1><p className="hero-intro">I am <strong>Olusola Ayodeji Ezekiel</strong>, a Product Manager across FinTech, digital payments, eCommerce and iGaming. Before building digital products, I spent more than a decade leading residential, commercial and public construction projects. That experience shaped my discipline, technical judgement and ownership of delivery.</p><div className="hero-actions"><a className="button primary" href="#products">Explore case studies <span>↘</span></a><a className="button text" href="#contact">Start a conversation <span>↗</span></a></div><div className="hero-cv-actions" aria-label="Download curriculum vitae"><a href="/documents/olusola-ayodeji-product-manager-cv.pdf" download>Download Product Manager CV <span>↓</span></a><a href="/documents/olusola-ayodeji-construction-cv.pdf" download>Download Construction CV <span>↓</span></a></div></div><aside className="portrait-panel"><button className={`portrait-welcome ${showWelcome?"is-welcoming":""}`} onClick={()=>setShowWelcome(value=>!value)} aria-expanded={showWelcome} aria-label="Play Olusola's welcome greeting"><img src="/portfolio/bio-portrait.png" alt="Olusola Ayodeji Ezekiel"/><span className="welcome-message" aria-live="polite"><span className="wave-hand" aria-hidden="true">👋🏾</span><span><strong>Hi, welcome.</strong><small>I am Olusola Ayodeji Ezekiel.</small></span></span><span className="welcome-hint">Tap to say hello</span></button><div className="portrait-caption"><strong>4+ years</strong><span>Product management</span><strong>10+ years</strong><span>Project leadership</span></div></aside></section>
  <section className="statement"><p className="section-kicker">My point of view</p><blockquote>Good product management creates enough clarity for a team to solve the <em>right problem</em> and enough structure to deliver it well.</blockquote></section>
  <section className="section" id="products"><div className="section-heading"><div><p className="section-kicker">Selected product work</p><h2>Case studies in trust, payments and platforms.</h2></div><p>Each project is presented as a concise overview with an extended journal explaining the context, decisions, delivery process and lessons.</p></div><div className="case-list">{productCases.map(item=><article className="case-card" key={item.title}><div className="case-top"><span>{item.number}</span><p>{item.label}</p>{item.status&&<span className="case-status">{item.status}</span>}</div><div className="case-intro"><h3>{item.title}</h3><p>{item.summary}</p></div><Gallery item={item} onZoom={openZoom}/><div className="case-footer"><div className="feature-tags">{item.tags.map(t=><span key={t}>{t}</span>)}</div><button className="case-button" onClick={()=>setActive(item)}>{item.articleLabel}<span>↗</span></button></div></article>)}</div></section>
  <section className="capabilities section"><div className="section-heading compact"><div><p className="section-kicker">My product practice</p><h2>From insight to dependable delivery.</h2></div><p>Select any stage to read the journal behind the practice or download a copy.</p></div><div className="capability-grid">{practiceJournals.map(journal=><article className="practice-card" key={journal.title}><button className="practice-card-open" type="button" onClick={()=>setActivePractice(journal)} aria-label={`Read ${journal.title} product practice journal`}/><span>{journal.number}</span><h3>{journal.title}</h3><p>{journal.summary}</p><div className="practice-card-meta"><small>{journal.readTime}</small><strong>{journal.articleTitle}</strong></div><div className="practice-card-actions"><button type="button" onClick={()=>setActivePractice(journal)}>Read journal <span>↗</span></button><a href={journal.href} download>Download PDF <span>↓</span></a></div></article>)}</div></section>
  <section className="construction section" id="construction"><div className="section-heading"><div><p className="section-kicker">Construction leadership</p><h2>Delivery experience built on site.</h2></div><p>Six selected projects from more than a decade of structural supervision, multidisciplinary coordination and project leadership.</p></div><div className="construction-grid">{constructionCases.map(item=><article className="construction-card" key={item.title}><Gallery item={item} onZoom={openZoom}/><div className="construction-copy"><div className="case-top"><span>{item.number}</span><p>{item.label}</p></div><h3>{item.title}</h3><p className="location">{item.location}</p><p>{item.summary}</p><div className="feature-tags">{item.tags.map(t=><span key={t}>{t}</span>)}</div><button className="case-button" onClick={()=>setActive(item)}>{item.articleLabel}<span>↗</span></button></div></article>)}</div></section>
  <section className="about section" id="about"><div><p className="section-kicker">Professional summary</p><h2>Product thinking grounded in real-world delivery.</h2></div><div className="about-copy"><p className="lead">I am a Product Manager with experience across FinTech, digital payments, eCommerce and iGaming, backed by more than ten years leading construction and infrastructure delivery.</p><p>My earlier career progressed through site engineering, site management and project management across residential, commercial and public sector developments. I supervised structural execution, interpreted drawings, coordinated specialists, managed programmes and resources, protected quality and resolved problems where delays had real consequences.</p><p>That foundation now informs how I lead digital products. I bring structured discovery, clear documentation, technical curiosity and cross functional coordination to complex product work, from user research and roadmaps to sprint delivery, QA and optimisation.</p><div className="principles"><span>Clarity over noise</span><span>Users before assumptions</span><span>Outcomes over output</span></div></div></section>
  <section className="experience section"><div className="section-heading compact"><div><p className="section-kicker">Experience</p><h2>A cross industry journey.</h2></div></div><div className="timeline"><article><div><span>2025 to 2026</span><span>Product leadership</span></div><div><h3>Siiqo Marketplace</h3><p>Product strategy, marketplace experiences, Agile delivery and optimisation across payments, vendors, community and trust.</p></div></article><article><div><span>2025</span><span>FinTech product</span></div><div><h3>Canvoy Payment</h3><p>Product discovery, MVP definition, Jira ownership, Scrum leadership, payment flows and readiness.</p></div></article><article><div><span>Product</span><span>FinTech and iGaming</span></div><div><h3>Wayagram and BetBonanza</h3><p>Technical product coordination, production QA, social commerce, wallet and payments, plus sportsbook product experience.</p></div></article><article><div><span>10+ years</span><span>Project leadership</span></div><div><h3>Construction and infrastructure</h3><p>Site engineering and project leadership across residential, commercial and public developments.</p></div></article></div></section>
  <section className="insights section" id="insights"><div className="section-heading"><div><p className="section-kicker">LinkedIn insights</p><h2>Notes from the product journey.</h2></div><p>Short reflections on product discovery, delivery, collaboration and the everyday decisions behind useful products.</p></div><div className="insight-grid">{linkedinPosts.map((post,i)=><article key={post.href}><div><span>0{i+1}</span><small>{post.topic}</small></div><h3>{post.title}</h3><p>{post.text}</p><a href={post.href} target="_blank" rel="noreferrer">Read on LinkedIn ↗</a></article>)}</div><a className="linkedin-profile" href="https://www.linkedin.com/in/ayodeji-ezekiel-olusola/" target="_blank" rel="noreferrer">View my LinkedIn profile ↗</a></section>
  <section className="rough-space section" id="rough-space"><div className="section-heading"><div><p className="section-kicker">Rough Space</p><h2>The studio behind the work.</h2></div><p>A personal studio for music, short films, product notes and practical resources. This is where observation, craft and product thinking meet before an idea becomes polished.</p></div><div className="rough-grid"><article className="rough-card music-card"><div className="rough-card-heading"><span>01</span><div><p>Listening room</p><h3>Original music</h3></div></div><div className="audio-list"><div><div><strong>Era Transition</strong><small>Original track</small></div><audio controls preload="metadata"><source src="/rough-space/era-transition.mp3" type="audio/mpeg"/>Your browser does not support audio.</audio></div><div><div><strong>9–5 Lagos</strong><small>Original track</small></div><audio controls preload="metadata"><source src="/rough-space/nine-to-five-lagos.mp3" type="audio/mpeg"/>Your browser does not support audio.</audio></div></div></article><article className="rough-card film-card"><div className="rough-card-heading"><span>02</span><div><p>Moving ideas</p><h3>Video studio</h3></div></div><div className="studio-video-grid"><figure><video controls playsInline preload="none" poster="/rough-space/studio-film-poster.jpg"><source src="/rough-space/studio-film-web.mp4" type="video/mp4"/>Your browser does not support video.</video><figcaption><strong>Night Drive</strong><small>A visual storytelling experiment</small></figcaption></figure><figure><video controls playsInline preload="none" poster="/rough-space/studio-short-poster.jpg"><source src="/rough-space/studio-short-web.mp4" type="video/mp4"/>Your browser does not support video.</video><figcaption><strong>Canvoy concept walkthrough</strong><small>An early product experience in motion</small></figcaption></figure></div></article><article className="rough-card notebook-card"><div className="rough-card-heading"><span>03</span><div><p>Visual notebook</p><h3>Product experiments and artwork</h3></div></div><div className="note-gallery">{[{src:"/rough-space/insurpe-exploration.jpg",alt:"Insurpe product flow exploration",title:"Insurpe exploration"},{src:"/rough-space/pm-note-problem-solving.png",alt:"Product management as problem solving",title:"Problem solver note"},{src:"/rough-space/pm-note-validation.png",alt:"Feature validation product note",title:"Feature validation note"},{src:"/rough-space/signbridge-interface-1.png",alt:"SignBridge accessibility product interface",title:"SignBridge concept"},{src:"/rough-space/signbridge-interface-2.png",alt:"SignBridge sign language translation interface",title:"SignBridge interface study"},{src:"/rough-space/pm-note-payment-experience.png",alt:"Payment experience product note",title:"Payment experience thinking"},{src:"/rough-space/canvoy-design-workspace.jpg",alt:"Canvoy product design workspace",title:"Canvoy design workspace"}].map(note=><button key={note.src} onClick={()=>openZoom(note.src,note.alt)} aria-label={`Open ${note.alt}`}><img src={note.src} alt={note.alt}/><span>{note.title}</span></button>)}</div></article><article className="rough-card handbook-card"><div className="rough-card-heading"><span>04</span><div><p>Working library</p><h3>PM toolkit handbook</h3></div></div><p>A practical reference for Product Managers and Technical Product Managers. It brings together discovery, documentation, prioritisation, delivery, technical fluency, QA and stakeholder practices in one working guide.</p><div className="handbook-actions"><a className="button primary" href="/rough-space/pm-toolkit-handbook.pdf" target="_blank" rel="noreferrer">Read the handbook <span>↗</span></a><a className="button text" href="/rough-space/pm-toolkit-handbook.pdf" download>Download PDF <span>↓</span></a></div></article></div></section>
  <section className="mentors section"><div className="section-heading compact"><div><p className="section-kicker">Mentors</p><h2>People who shaped the journey.</h2></div></div><div className="mentor-grid">{mentors.map((mentor,i)=><article key={mentor.name}><span>{String(i+1).padStart(2,"0")}</span><div className="mentor-initials">{mentor.name.split(" ").slice(0,2).map(part=>part[0]).join("")}</div><h3>{mentor.name}</h3><p>Mentor and valued influence on my professional growth.</p>{mentor.href?<a className="mentor-link" href={mentor.href} target="_blank" rel="noreferrer">View LinkedIn profile ↗</a>:<span className="mentor-pending">LinkedIn link pending</span>}</article>)}</div></section>
  <section className="resume section"><div><p className="section-kicker">Curriculum vitae</p><h2>Two disciplines.<br/>One delivery mindset.</h2></div><div className="resume-cards"><a href="/documents/olusola-ayodeji-product-manager-cv.pdf" target="_blank"><span>Product</span><h3>Product Manager CV</h3><p>Product strategy, discovery, roadmaps, Agile delivery and technical coordination.</p><b>View or download PDF ↗</b></a><a href="/documents/olusola-ayodeji-construction-cv.pdf" target="_blank"><span>Construction</span><h3>Civil Engineering CV</h3><p>Site engineering, structural supervision and construction project leadership.</p><b>View or download PDF ↗</b></a></div></section>
  <section className="toolkit section"><div><p className="section-kicker">Product toolkit</p><h2>Tools support the work.<br/>Judgement drives it.</h2></div><div className="tool-cloud">{["Jira","Confluence","Trello","Notion","Miro","Figma","FigJam","Canva","Slack","RICE","MoSCoW","Scrum","APIs","QA","Analytics"].map(t=><span key={t}>{t}</span>)}</div></section>
  <section className="contact section" id="contact"><p className="section-kicker">Lagos, Nigeria · Open to opportunities and collaboration</p><h2>Let&apos;s build something useful.</h2><p>I am open to Product Manager opportunities, construction consultation and collaboration with founders, teams and organisations.</p><div className="contact-actions" aria-label="Contact options"><a className="contact-icon light" href="mailto:Olusola40@gmail.com" aria-label="Send Olusola an email"><Icon name="mail"/><span>Email</span></a><a className="contact-icon outline" href="https://wa.me/2349015934337" target="_blank" rel="noreferrer" aria-label="Message Olusola on WhatsApp"><Icon name="whatsapp"/><span>WhatsApp</span></a><a className="contact-icon outline" href="tel:+2349015934337" aria-label="Call Olusola"><Icon name="phone"/><span>Call</span></a><a className="contact-icon outline" href="https://www.linkedin.com/in/ayodeji-ezekiel-olusola/" target="_blank" rel="noreferrer" aria-label="View Olusola on LinkedIn"><Icon name="linkedin"/><span>LinkedIn</span></a></div><p className="phone">+234 901 593 4337</p></section>
  <aside ref={contactRef} className={`floating-contact ${contactOpen?"is-open":""} ${contactPosition?"is-positioned":""} ${contactDragging?"is-dragging":""}`} style={contactPosition?{left:contactPosition.x,top:contactPosition.y,right:"auto",bottom:"auto",transform:"none"}:undefined} aria-label="Quick contact"><div className="floating-contact-list" id="quick-contact-list" aria-hidden={!contactOpen}><a href="mailto:Olusola40@gmail.com" aria-label="Email" title="Email" tabIndex={contactOpen?0:-1}><Icon name="mail"/></a><a href="https://wa.me/2349015934337" target="_blank" rel="noreferrer" aria-label="WhatsApp" title="WhatsApp" tabIndex={contactOpen?0:-1}><Icon name="whatsapp"/></a><a href="tel:+2349015934337" aria-label="Call" title="Call" tabIndex={contactOpen?0:-1}><Icon name="phone"/></a><a href="https://www.linkedin.com/in/ayodeji-ezekiel-olusola/" target="_blank" rel="noreferrer" aria-label="LinkedIn" title="LinkedIn" tabIndex={contactOpen?0:-1}><Icon name="linkedin"/></a></div><button className="floating-contact-toggle" type="button" onPointerDown={startContactDrag} onPointerMove={moveContactDrag} onPointerUp={finishContactDrag} onPointerCancel={finishContactDrag} onClick={toggleContact} aria-expanded={contactOpen} aria-controls="quick-contact-list" aria-label={contactOpen?"Close contact options. Drag to move.":"Open contact options. Drag to move."}><Icon name="chat"/><span aria-hidden="true">×</span></button></aside>
  <footer><div className="brand"><span>OLUSOLA AYODEJI EZEKIEL</span><small>Product Manager</small></div><div className="footer-socials"><a href="mailto:Olusola40@gmail.com" aria-label="Email"><Icon name="mail"/></a><a href="https://wa.me/2349015934337" target="_blank" rel="noreferrer" aria-label="WhatsApp"><Icon name="whatsapp"/></a><a href="https://www.linkedin.com/in/ayodeji-ezekiel-olusola/" target="_blank" rel="noreferrer" aria-label="LinkedIn"><Icon name="linkedin"/></a></div><a href="#top">Back to top ↑</a></footer>
  {active&&<CaseModal item={active} onClose={()=>setActive(null)} onZoom={openZoom}/>} {activePractice&&<PracticeJournalModal journal={activePractice} onClose={()=>setActivePractice(null)}/>} {zoom&&<div className="lightbox" role="dialog" aria-modal="true" aria-label="Expanded image" onClick={()=>setZoom(null)}><button aria-label="Close image">Close ×</button><img src={zoom.src} alt={zoom.alt}/><p>{zoom.alt}</p></div>}
 </main>}
